{"command":"python3 << 'EOF'
import csv

# Verify the CSV is valid and parseable
with open('outputs/t08_pois_clean.csv', 'r', newline='') as f:
    reader = csv.reader(f)
    rows = list(reader)

print(f"Number of rows (including header): {len(rows)}")
print(f"Header: {rows[0]}")
print(f"Number of data rows: {len(rows) - 1}")

# Verify all rows have the correct number of columns
header_cols = len(rows[0])
for i, row in enumerate(rows):
    if len(row) != header_cols:
        print(f"Row {i} has {len(row)} columns, expected {header_cols}")
        break
else:
    print("All rows have correct number of columns")

# Verify latitude/longitude are numeric and in valid ranges
for row in rows[1:]:
    qid, label, poi_type, lat, lon, source = row
    try:
        lat = float(lat)
        lon = float(lon)
        if not (-90 <= lat <= 90):
            print(f"Invalid latitude for {qid}: {lat}")
        if not (-180 <= lon <= 180):
            print(f"Invalid longitude for {qid}: {lon}")
    except ValueError as e:
        print(f"Non-numeric lat/lon for {qid}: {e}")
        break
else:
    print("All latitudes and longitudes are valid numeric values in valid ranges")

# Verify all labels are non-empty
for row in rows[1:]:
    _, label, _, _, _, _ = row
    if not label or label.strip() == '':
        print(f"Empty label for qid: {row[0]}")
        break
else:
    print("All labels are non-empty")
EOF"}
